class A:
 def __hash__(self): raise ValueError("hash")
 def __eq__(self,other): raise ValueError("equal")
 def __getattribute__(self,name): raise ValueError("attribute")
a=A()
value=int("1234567890123456789012345")
print(id(a)!=id(value),a is not value,value is not a,id(value)==id(value))

def forward(value): return value
value=int("1234567890123456789012345")
identity=id(value)
try: raise ValueError(value)
except ValueError: print(forward(value) is value,id(forward(value))==identity)
